sercontent.com/u/273673612?v=4","gravatar_id":"","url":"https://api.github.com/users/Tomasrgbsf","html_url":"https://github.com/Tomasrgbsf","followers_url":"https://api.github.com/users/Tomasrgbsf/followers","following_url":"https://api.github.com/users/Tomasrgbsf/following{/other_user}","gists_url":"https://api.github.com/users/Tomasrgbsf/gists{/gist_id}","starred_url":"https://api.github.com/users/Tomasrgbsf/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Tomasrgbsf/subscriptions","organizations_url":"https://api.github.com/users/Tomasrgbsf/orgs","repos_url":"https://api.github.com/users/Tomasrgbsf/repos","events_url":"https://api.github.com/users/Tomasrgbsf/events{/privacy}","received_events_url":"https://api.github.com/users/Tomasrgbsf/received_events","type":"User","user_view_type":"public","site_admin":false},"parents":[{"sha":"942d470d155c65ba7235eb19c5bbfd07f1ce2ad0","url":"https://api.github.com/repos/TrillionniumFoundation/hepta-runtime/commits/942d470d155c65ba7235eb19c5bbfd07f1ce2ad0","html_url":"https://github.com/TrillionniumFoundation/hepta-runtime/commit/942d470d155c65ba7235eb19c5bbfd07f1ce2ad0"}],"stats":{"total":52,"additions":46,"deletions":6},"files":[{"sha":"6eadf969ced1d6b5e4f3633308f9876b6cbaca89","filename":"src/mcp/runtime/request_archive_index_tests.rs","status":"modified","additions":46,"deletions":6,"changes":52,"blob_url":"https://github.com/TrillionniumFoundation/hepta-runtime/blob/c81a938150d2e533843a42af77739cb888812338/src%2Fmcp%2Fruntime%2Frequest_archive_index_tests.rs","raw_url":"https://github.com/TrillionniumFoundation/hepta-runtime/raw/c81a938150d2e533843a42af77739cb888812338/src%2Fmcp%2Fruntime%2Frequest_archive_index_tests.rs","contents_url":"https://api.github.com/repos/TrillionniumFoundation/hepta-runtime/contents/src%2Fmcp%2Fruntime%2Frequest_archive_index_tests.rs?ref=c81a938150d2e533843a42af77739cb888812338","patch":"@@ -971,21 +971,61 @@ fn checkpoint_verifies_every_inode_and_ctime_on_cold_load() {
 		.unwrap()
 		.path();
 	let bytes = std::fs::read(&receipt).unwrap();
+	let original: Record = serde_json::from_slice(&bytes).unwrap();
+	let filename = receipt.file_name().unwrap().to_str().unwrap();
+	let key = id(receipt.file_stem().unwrap().to_str().unwrap()).unwrap();
+	let prior_stamp = stamp(&archive, filename).unwrap();
+	let watched = content_version(&archive).unwrap().is_some();
 	std::fs::write(&receipt, &bytes).unwrap();
-	// A live watch rejects an outside edit; a fresh process starts a new epoch.
-	assert!(cached(&slot, deadline).unwrap().is_none());
+	let rewritten_stamp = stamp(&archive, filename).unwrap();
+	assert!(rewritten_stamp != prior_stamp);
+	// A live watch rejects an outside edit. Without one, the cold loader must
+	// reread the complete original and may accept identical bytes with a new stamp.
+	let observed = cached(&slot, deadline).unwrap();
+	if watched {
+		assert!(observed.is_none());
+	} else {
+		assert!(content_version(&archive).unwrap().is_none());
+		let db = observed.unwrap().database;
+		let transaction = db.begin_read().unwrap();
+		let rows = transaction.open_table(ROWS).unwrap();
+		let entry: Entry =
+			codec::decode(rows.get(key.as_slice()).unwrap().unwrap().value()).unwrap();
+		assert!(entry.record == original);
+		assert!(entry.stamp == rewritten_stamp);
+		assert_eq!(std::fs::read(&receipt).unwrap(), bytes);
+	}
 	slot.state.lock().unwrap().version = content_version(&archive).unwrap();
 	let db = cached(&slot, deadline).unwrap().unwrap().database;
 	let transaction = db.begin_read().unwrap();
 	let rows = transaction.open_table(ROWS).unwrap();
-	let key = id(receipt.file_stem().unwrap().to_str().unwrap()).unwrap();
 	let entry: Entry = codec::decode(rows.get(key.as_slice()).unwrap().unwrap().value()).unwrap();
-	assert!(
-		entry.stamp == stamp(&archive, receipt.file_name().unwrap().to_str().unwrap()).unwrap()
-	);
+	assert!(entry.record == original);
+	assert!(entry.stamp == rewritten_stamp);
+	assert!(entry.stamp == stamp(&archive, filename).unwrap());
 	drop(rows);
 	drop(transaction);
 	drop(db);
+	if !watched {
+		// A matching length cannot conceal a different, otherwise valid identity.
+		let text = std::str::from_utf8(&bytes).unwrap();
+		assert_eq!(text.matches("host_list").count(), 1);
+		let changed = text.replacen("host_list", "file_info", 1).into_bytes();
+		assert_eq!(changed.len(), bytes.len());
+		let mut altered = original.clone();
+		altered.tool_name = "file_info".into();
+		assert!(serde_json::from_slice::<Record>(&changed).unwrap() == altered);
+		std::fs::write(&receipt, &changed).unwrap();
+		let error = cached(&slot, deadline)
+			.err()
+			.expect("unwatched cold validation must reject an original identity change");
+		assert!(matches!(
+			error.downcast_ref::<OriginalRecordConflict>(),
+			Some(OriginalRecordConflict::Identity)
+		));
+		assert_eq!(std::fs::read(&receipt).unwrap(), changed);
+		std::fs::write(&receipt, &bytes).unwrap();
+	}
 	std::fs::set_permissions(
 		root.path().join(CACHE_NAME),
 		std::fs::Permissions::from_mode(0o644),"}]}

